<template><div class="space-y-6"><div class="flex items-center justify-between gap-3"><h1 class="text-3xl font-bold">My Recipes</h1><NuxtLink to="/recipes/new" class="btn">+ New Recipe</NuxtLink></div><input v-model="search" placeholder="Search your recipes…" aria-label="Search recipes"/><p v-if="error" class="error">{{error}}</p><p v-else-if="loading">Loading recipes…</p><p v-else-if="!recipes.length">No recipes found. Add your first recipe!</p><div v-else class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"><NuxtLink v-for="r in recipes" :key="r.id" :to="`/recipes/${r.id}`" class="card hover:shadow-md transition"><div class="bg-stone-100 rounded-lg h-36 mb-3 overflow-hidden"><img v-if="images[r.id]" :src="images[r.id]" :alt="r.title" class="w-full h-full object-cover"/><div v-else class="h-full grid place-items-center text-5xl">🍽️</div></div><h2 class="font-bold text-lg">{{r.title}}</h2><p class="text-sm text-stone-500">{{r.category}} · {{r.visibility}}</p></NuxtLink></div></div></template>
<script setup lang="ts">
definePageMeta({middleware:'auth'});import type {Recipe} from '~/types/recipe'
const repo=useRecipeRepository(),search=ref(''),recipes=ref<Recipe[]>([]),images=reactive<Record<string,string>>({}),error=ref(''),loading=ref(true)
async function load(){loading.value=true;error.value='';try{recipes.value=await repo.list(search.value);await Promise.all(recipes.value.filter(r=>r.cover_image_path).map(async r=>{try{images[r.id]=await repo.imageUrl(r.cover_image_path!)}catch{}}))}catch(e:any){error.value=e.message||'Unable to load recipes'}finally{loading.value=false}}
watch(search,()=>load());onMounted(load)
</script>
